/* FitΛ visual prototype. All health/device values are fictional demo data. */
'use strict';
const paths={
home:'<path d="m3 10 9-7 9 7v9a2 2 0 0 1-2 2h-4v-7H9v7H5a2 2 0 0 1-2-2Z"/>',
chart:'<path d="M4 20V10m5 10V4m6 16v-8m5 8V7"/>',watch:'<rect x="6" y="6" width="12" height="12" rx="4"/><path d="m9 6 1-4h4l1 4m-6 12 1 4h4l1-4m-3-9v3l2 1"/>',
user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',
moon:'<path d="M21 13a9 9 0 0 1-10-10A9 9 0 1 0 21 13Z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.4 1.4m11.2 11.2L19 19M5 19l1.4-1.4M17.6 6.4 19 5"/>',
'arrow-right':'<path d="M4 12h16m-6-6 6 6-6 6"/>','arrow-up-right':'<path d="M5 19 19 5M5 5h14v14"/>',
'chevron-right':'<path d="m9 5 7 7-7 7"/>','chevron-left':'<path d="m15 5-7 7 7 7"/>',
bluetooth:'<path d="m7 7 10 10-5 5V2l5 5L7 17"/>',battery:'<rect x="2" y="7" width="18" height="10" rx="2"/><path d="M23 10v4M5 10v4m3-4v4m3-4v4m3-4v4"/>',
signal:'<path d="M3 20v-4m5 4v-8m5 8V8m5 12V4"/>',wifi:'<path d="M2 8a17 17 0 0 1 20 0M5 12a12 12 0 0 1 14 0m-11 4a6 6 0 0 1 8 0"/><circle cx="12" cy="20" r=".8" fill="currentColor"/>',
target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',
sparkles:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5ZM20 2v4m-2-2h4"/>',
close:'<path d="m6 6 12 12M6 18 18 6"/>',check:'<path d="m5 12 4 4L19 6"/>',
steps:'<ellipse cx="8" cy="7" rx="3" ry="5" transform="rotate(-20 8 7)"/><ellipse cx="16" cy="15" rx="3" ry="5" transform="rotate(-20 16 15)"/><path d="m5 15 2 3m8-16 2 3"/>',
shield:'<path d="M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6Z"/><path d="m8 12 3 3 5-6"/>',
bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M9 21h6"/>',
palette:'<circle cx="12" cy="12" r="9"/><circle cx="8" cy="9" r="1"/><circle cx="12" cy="6" r="1"/><circle cx="16" cy="9" r="1"/><path d="M20 14h-5a3 3 0 0 0-3 3v4"/>',
info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',
link:'<path d="m10 13 4-4m-7 7-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m4 2 2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0" transform="translate(2 -1)"/>',
refresh:'<path d="M20 8a9 9 0 0 0-16-2L2 9m0-6v6h6m-4 7a9 9 0 0 0 16 2l2-3m0 6v-6h-6"/>',
phone:'<rect x="6" y="2" width="12" height="20" rx="3"/><path d="M10 5h4m-3 14h2"/>',
edit:'<path d="m14 4 6 6M4 20l5-1L21 7a2 2 0 0 0-5-5L4 14Z"/>',
clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
leaf:'<path d="M20 3c0 11-2 17-9 17a7 7 0 0 1-7-7c0-7 8-4 16-10ZM4 21 15 10"/>'};
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.info}</svg>`;
const mountIcons=()=>document.querySelectorAll('[data-icon]').forEach(el=>{el.outerHTML=icon(el.dataset.icon)});
const $=s=>document.querySelector(s);
const fmt=n=>Math.round(n).toLocaleString('pt-BR');
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let saved={};try{saved=JSON.parse(localStorage.getItem('fitlambda-design-v2')||'{}')}catch(_){}
if(!saved||typeof saved!=='object')saved={};
const state={screen:'today',theme:saved.theme==='light'?'light':'dark',goal:[5000,6000,7000,8000,9000,10000,11000,12000,13000,14000,15000].includes(saved.goal)?saved.goal:10000,name:typeof saved.name==='string'&&saved.name.trim()?saved.name.slice(0,28):'Antonio',face:[1,2,3].includes(saved.face)?saved.face:1,connected:false,period:'week',metric:'steps',weekOffset:0,selectedBar:6,notifications:false};
function persist(){try{localStorage.setItem('fitlambda-design-v2',JSON.stringify({theme:state.theme,goal:state.goal,name:state.name,face:state.face}))}catch(_){}}
const demo=()=>'<p class="screen-demo">Prévia visual · dados de exemplo</p>';
const notes={today:['Menos ruído.<br>Mais movimento.','Um olhar é o suficiente para entender seu dia. O que importa vem primeiro.'],trends:['Pequenos passos.<br>Novas perspectivas.','Seu histórico ganha clareza. Explore os gráficos e descubra o valor da consistência.'],band:['Uma conexão.<br>Mais possibilidades.','O lugar da sua Fit3: bateria, aparência e controles reunidos em uma tela tranquila.'],profile:['Do seu jeito.<br>No seu tempo.','Metas, aparência e preferências. Uma experiência que se adapta a você.']};
function ring(){const p=Math.min(8432/state.goal,1),len=2*Math.PI*88*.75;return `<svg class="activity-ring" viewBox="0 0 260 225" role="img" aria-label="8.432 passos de uma meta de ${fmt(state.goal)}, ${Math.round(8432/state.goal*100)} por cento"><circle class="ring-ticks" cx="130" cy="112" r="102" fill="none" stroke-width="2" stroke-dasharray="1 8" opacity=".6"/><circle class="ring-track" cx="130" cy="112" r="88" fill="none" stroke-width="10" stroke-dasharray="${len} 553" stroke-linecap="round" transform="rotate(135 130 112)"/><circle class="ring-progress" cx="130" cy="112" r="88" fill="none" stroke-width="10" stroke-dasharray="${len*p} 553" stroke-linecap="round" transform="rotate(135 130 112)"/><g color="var(--accent)"><path d="m124 67 4-8m7 8 4-8m-12 10 9 0" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></g><text x="130" y="118" text-anchor="middle" class="ring-number">8.432</text><text x="130" y="139" text-anchor="middle" class="ring-caption">de ${fmt(state.goal)} passos</text><text x="130" y="193" text-anchor="middle" class="ring-percent">${Math.round(8432/state.goal*100)}% da meta</text></svg>`}
function today(){return `<section class="screen" aria-label="Resumo do dia"><p class="app-kicker">DOMINGO, 15 NOV</p><div class="greeting-row"><h1 class="greeting">Boa noite,<br><strong>${escapeHTML(state.name.split(' ')[0])}.</strong></h1><button class="avatar" data-nav="profile" aria-label="Abrir seu perfil">${escapeHTML(state.name[0].toUpperCase())}R</button></div><div class="connection-row"><button class="connection-badge" data-nav="band">${icon('watch')} Galaxy Fit3 <span class="demo-pill">Demo</span></button><span class="battery-label">${icon('battery')} 78%</span></div><section class="activity-card" aria-label="Seu movimento"><div class="card-heading"><span>SEU MOVIMENTO</span><button class="icon-btn" data-action="goal" aria-label="Editar meta de passos">${icon('target')}</button></div><div class="ring-wrap">${ring()}</div><p class="ring-footer">${state.goal>8432?`Faltam ${fmt(state.goal-8432)} passos. Você está perto.`:'Meta alcançada. Cada passo conta.'}</p><div class="stat-trio"><div><span class="stat-value">5,8<small>km</small></span><span class="stat-label">Distância</span></div><div><span class="stat-value">382<small>kcal</small></span><span class="stat-label">Energia ativa</span></div><div><span class="stat-value">42<small>min</small></span><span class="stat-label">Em movimento</span></div></div></section><div class="section-heading"><h2>Seu corpo, em foco.</h2><span>HOJE</span></div><div class="vitals-grid"><button class="vital vital-heart" data-action="heart" aria-label="Ver detalhes de frequência cardíaca, 68 batimentos por minuto"><div class="vital-top">${icon('heart')} Coração</div><div class="vital-value">68<small>bpm</small></div><div class="vital-bottom">Última leitura · 20:12</div><svg class="spark" viewBox="0 0 130 30" aria-hidden="true"><path d="M0 18h20l7-5 6 8 8-18 9 24 7-12 6 3h12l6-5 6 6h11l6-4 7 3h20" stroke-width="1.5"/></svg></button><button class="vital vital-sleep" data-action="sleep" aria-label="Ver detalhes do sono, 7 horas e 32 minutos"><div class="vital-top">${icon('moon')} Sono</div><div class="vital-value">7<small>h</small> 32<small>min</small></div><div class="vital-bottom">Tempo total dormindo</div><div class="sleep-mini" aria-hidden="true">${[9,18,22,13,20,16,22,15,20,10,22,18].map(x=>`<i style="height:${x}px"></i>`).join('')}</div></button></div><button class="insight" data-nav="trends">${icon('sparkles')}<div><strong>Um passo de cada vez.</strong><p>Você alcançou sua meta em ${[10800,10100,10400,11500,6800,8487,8432].filter(v=>v>=state.goal).length} dos últimos 7 dias. Veja a sua evolução.</p></div></button><p class="data-footnote">Dados fictícios para explorar a interface.<br>Sua pulseira ainda não está conectada.</p></section>`}
function chartData(){const isWeek=state.period==='week';const names=isWeek?['Seg','Ter','Qua','Qui','Sex','Sáb','Dom']:['1–4','5–8','9–12','13–15'];let values=state.metric==='steps'?(isWeek?[10800,10100,10400,11500,6800,8487,8432]:[7350,8020,9120,9240]):state.metric==='sleep'?(isWeek?[7.1,7.6,6.8,8.0,7.4,8.2,7.53]:[7.1,7.4,7.6,7.53]):(isWeek?[65,67,64,69,66,63,68]:[68,67,66,65]);if(state.weekOffset<0)values=values.map((v,i)=>state.metric==='steps'?Math.round(v*(.83+(i%3)*.02)):state.metric==='sleep'?v-.3:v+2);return {names,values,max:state.metric==='steps'?12000:state.metric==='sleep'?10:100,unit:state.metric==='steps'?'passos':state.metric==='sleep'?'de sono':'bpm',avg:isWeek?values.reduce((a,b)=>a+b,0)/values.length:values.reduce((a,b,i)=>a+b*[4,4,4,3][i],0)/15}}
function metricFormat(v){return state.metric==='steps'?fmt(v):state.metric==='sleep'?`${Math.floor(v)}h${String(Math.round((v%1)*60)).padStart(2,'0')}`:fmt(v)}
function trends(){const d=chartData();const sel=Math.min(state.selectedBar,d.values.length-1);state.selectedBar=sel;return `<section class="screen" aria-label="Sua evolução"><p class="app-kicker">CADA DIA CONTA</p><h1 class="page-title">Seu ritmo.</h1><p class="page-subtitle">O progresso mora na constância.</p>${demo()}<div class="segment" role="group" aria-label="Período do gráfico"><button data-period="week" class="${state.period==='week'?'active':''}" aria-pressed="${state.period==='week'}">Semana</button><button data-period="month" class="${state.period==='month'?'active':''}" aria-pressed="${state.period==='month'}">Mês</button></div><div class="period-row"><button data-offset="-1" aria-label="Período anterior" ${state.weekOffset===-1?'disabled':''}>${icon('chevron-left')}</button><span>${state.period==='week'?(state.weekOffset===0?'9 — 15 de novembro':'2 — 8 de novembro'):(state.weekOffset===0?'1 — 15 de novembro':'1 — 15 de outubro')}</span><button data-offset="1" aria-label="Próximo período" ${state.weekOffset===0?'disabled':''}>${icon('chevron-right')}</button></div><div class="chart-card"><div class="chart-summary"><span class="big-number">${metricFormat(d.avg)}</span><span class="growth">${state.period==='week'?'7 dias':'15 dias'}</span></div><p class="chart-caption">${state.metric==='steps'?'Média diária de passos':state.metric==='sleep'?'Média de sono por noite':'Média de frequência em repouso'} · exemplo</p><div class="chart-plot"><div class="bars" role="group" aria-label="Gráfico interativo de ${d.unit}. Toque em uma barra para ver o valor.">${d.values.map((v,i)=>`<button class="bar-group ${i===sel?'active':''}" data-bar="${i}" aria-label="${d.names[i]}, ${metricFormat(v)} ${d.unit}" aria-pressed="${i===sel}"><span class="bar-visual" style="height:${v/d.max*100}%"></span></button>`).join('')}</div><div class="chart-scale" aria-hidden="true"><span>${state.metric==='steps'?'12k':d.max}</span><span>${state.metric==='steps'?'6k':d.max/2}</span><span>0</span></div></div><div class="bar-labels" aria-hidden="true">${d.names.map(x=>`<span>${x}</span>`).join('')}</div><div class="chart-selection" aria-live="polite"><span>${d.names[sel]}${state.period==='month'?' de '+(state.weekOffset===0?'novembro':'outubro'):''}</span><strong>${metricFormat(d.values[sel])} ${state.metric==='sleep'?'de sono':d.unit}</strong></div></div><div class="metric-options" role="group" aria-label="Métrica do gráfico">${[['steps','steps','Passos'],['sleep','moon','Sono'],['heart','heart','Coração']].map(([id,ic,label])=>`<button data-metric="${id}" class="${state.metric===id?'active':''}" aria-pressed="${state.metric===id}">${icon(ic)}${label}</button>`).join('')}</div><div class="section-heading"><h2>Um olhar mais de perto.</h2></div><div class="info-list"><div class="info-row">${icon('target')}<div>Consistência<small>Meta de 10.000 passos · semana de exemplo</small></div><span class="row-value">4 de 7 dias</span></div><div class="info-row">${icon('steps')}<div>Seu melhor dia<small>11.500 passos · semana de exemplo</small></div><span class="row-value">Quinta</span></div></div><p class="data-footnote">Histórico ilustrativo. Nenhum dado de saúde foi coletado.</p></section>`}
function watchFace(face=state.face){return `<div class="watch-face face-${face}"><span class="watch-date">DOM, 15 NOV</span><span class="watch-time">09<span>41</span></span><span class="watch-steps">8.432 PASSOS</span></div>`}
function band(){return `<section class="screen" aria-label="Sua pulseira"><p class="app-kicker">SEMPRE COM VOCÊ</p><h1 class="page-title">Sua Fit.</h1><p class="page-subtitle">Pequena no pulso. Parte do seu dia.</p>${demo()}<div class="band-display" aria-label="Ilustração conceitual da Galaxy Fit3"><div class="band"><div class="strap"></div><div class="watch-case">${watchFace()}</div></div></div><div class="band-name"><h2>Galaxy Fit3</h2><p>${state.connected?'Conexão simulada · modo demonstração':'Pronta para fazer parte do seu ritmo.'}</p></div><div class="band-stats"><span>${icon('battery')} 78% de bateria</span><span>${icon('bluetooth')} ${state.connected?'Demo conectada':'Não conectada'}</span></div><button class="primary-btn" data-action="pair">${icon(state.connected?'refresh':'link')} ${state.connected?'Rever demonstração':'Simular conexão'}</button><div class="info-list band-options"><button class="info-row" data-action="faces">${icon('palette')}<div>Seu estilo, no pulso<small>Explore 3 conceitos de mostrador</small></div>${icon('chevron-right','chevron')}</button><button class="info-row" data-action="sync">${icon('refresh')}<div>Sincronização<small>Conheça a experiência planejada</small></div>${icon('chevron-right','chevron')}</button><button class="info-row" data-action="device-info">${icon('info')}<div>Sobre a pulseira<small>Galaxy Fit3 · SM-R390</small></div>${icon('chevron-right','chevron')}</button></div><p class="data-footnote">Ilustração conceitual. Bateria e mostradores simulados.<br>Nenhum comando é enviado à sua Fit3.</p></section>`}
function profile(){return `<section class="screen" aria-label="Seu perfil"><p class="app-kicker">UM ESPAÇO SEU</p><h1 class="page-title">Do seu jeito.</h1><div class="profile-hero"><button class="avatar" data-action="name" aria-label="Editar nome">${escapeHTML(state.name[0].toUpperCase())}R</button><div><h2>${escapeHTML(state.name)}</h2><p>Seu ritmo. Suas escolhas.</p></div><button class="icon-btn" data-action="name" aria-label="Editar perfil" style="margin-left:auto">${icon('edit')}</button></div><div class="profile-banner"><span class="lambda">Λ</span><div><strong>O essencial é você.</strong><p>Uma experiência simples.<br>Com espaço para ir além.</p></div></div><p class="group-title">SEU DIA A DIA</p><div class="info-list"><button class="info-row" data-action="goal">${icon('target')}<div>Meta de passos</div><span class="row-value">${fmt(state.goal)}</span>${icon('chevron-right','chevron')}</button><button class="info-row" data-action="theme">${icon(state.theme==='dark'?'moon':'sun')}<div>Aparência</div><span class="row-value">${state.theme==='dark'?'Escura':'Clara'}</span>${icon('chevron-right','chevron')}</button><button class="info-row" data-action="notifications" role="switch" aria-checked="${state.notifications}" aria-label="Prévia de lembretes"><div>Prévia de lembretes<small>Somente uma simulação visual</small></div><span class="toggle ${state.notifications?'on':''}" aria-hidden="true"></span></button></div><p class="group-title">SEUS DADOS</p><div class="info-list"><button class="info-row" data-action="health">${icon('heart')}<div>Apple Saúde<small>Integração planejada</small></div>${icon('chevron-right','chevron')}</button><button class="info-row" data-action="privacy">${icon('shield')}<div>Privacidade</div>${icon('chevron-right','chevron')}</button><button class="info-row" data-action="welcome">${icon('sparkles')}<div>Rever boas-vindas</div>${icon('chevron-right','chevron')}</button></div><div class="profile-version"><b>FitΛ</b>Design preview 0.2.0<br>Feito para o seu ritmo.</div><p class="data-footnote">Seus ajustes visuais ficam apenas neste navegador.</p></section>`}
const renderers={today,trends,band,profile};
function render(resetScroll=false){$('#app-content').innerHTML=renderers[state.screen]();document.querySelectorAll('[data-nav]').forEach(el=>{const selected=el.dataset.nav===state.screen;el.classList.toggle(el.closest('.tabbar')?'selected':'active',selected);if(el.closest('.tabbar')){if(selected)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current')}});$('#context-title').innerHTML=notes[state.screen][0];$('#context-copy').textContent=notes[state.screen][1];if(resetScroll)$('#app-scroll').scrollTop=0;}
function navigate(screen){if(!renderers[screen])return;state.screen=screen;render(true)}
function theme(){state.theme=state.theme==='dark'?'light':'dark';applyTheme();persist();render()}
function applyTheme(){$('#phone').dataset.theme=state.theme;$('#theme-label').textContent=state.theme==='dark'?'Escura':'Clara';document.querySelector('meta[name=theme-color]').content=state.theme==='dark'?'#101410':'#f5f6ef'}
let focusBeforeSheet=null,toastTimeout;
function openSheet(title,body,kind=''){if($('#sheet-backdrop').hidden)focusBeforeSheet=document.activeElement;$('#sheet').dataset.kind=kind;$('#sheet').innerHTML=`<div class="sheet-heading"><h2 id="sheet-title">${title}</h2><button class="icon-btn" data-action="close" aria-label="Fechar">${icon('close')}</button></div>${body}`;$('#sheet-backdrop').hidden=false;$('#app-scroll').inert=true;$('.tabbar').inert=true;document.querySelectorAll('.intro,.design-notes,.studio-header').forEach(el=>el.inert=true);$('#sheet').focus();$('#sheet').scrollTop=0}
function closeSheet(){$('#sheet-backdrop').hidden=true;$('#app-scroll').inert=false;$('.tabbar').inert=false;document.querySelectorAll('.intro,.design-notes,.studio-header').forEach(el=>el.inert=false);if(focusBeforeSheet&&focusBeforeSheet.isConnected)focusBeforeSheet.focus();else $('.tabbar .selected').focus()}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('show'),3400)}
function goalSheet(){openSheet('Um passo além.',`<p>Escolha uma meta que combine com o seu dia.</p><div class="goal-value" id="goal-value">${fmt(state.goal)}</div><p class="goal-caption">passos por dia</p><label class="sr-only" for="goal-range">Meta diária de passos</label><input id="goal-range" class="goal-slider" type="range" min="5000" max="15000" step="1000" value="${state.goal}"><div class="range-extremes"><span>5.000 passos</span><span>15.000 passos</span></div><div class="goal-presets" role="group" aria-label="Metas sugeridas">${[6000,8000,10000].map(n=>`<button data-goal="${n}" class="${n===state.goal?'active':''}">${fmt(n)}</button>`).join('')}</div><button class="primary-btn" data-action="save-goal">Salvar minha meta ${icon('check')}</button><p class="discreet">Ajuste visual. Não altera a meta na pulseira.</p>`,'goal')}
function welcome(){openSheet('Bem-vindo ao FitΛ.',`<div class="welcome-symbol" aria-hidden="true">Λ</div><h3 class="welcome-title">Sua Fit.<br>Novas possibilidades.</h3><p class="welcome-copy">Uma nova forma de acompanhar<br>o que move você.</p><div class="welcome-features"><div class="welcome-feature">${icon('steps')}<div><strong>Seu dia, com clareza</strong><p>Movimento e bem-estar em um só lugar.</p></div></div><div class="welcome-feature">${icon('watch')}<div><strong>Um espaço para sua Fit3</strong><p>Pensado para a experiência do iPhone.</p></div></div><div class="welcome-feature">${icon('leaf')}<div><strong>Simples, desde o primeiro toque</strong><p>O essencial, do seu jeito.</p></div></div></div><button class="primary-btn" data-action="start-explore">Explorar o FitΛ ${icon('arrow-right')}</button><p class="discreet">Protótipo com dados fictícios. Sem conexão Bluetooth.</p>`,'welcome')}
function heartSheet(){openSheet('Seu coração.',`<p class="sheet-kicker">FREQUÊNCIA CARDÍACA · EXEMPLO</p><div class="detail-value">68 <small>bpm</small></div><p>Última leitura de demonstração às 20:12.</p><svg class="detail-line" viewBox="0 0 320 100" role="img" aria-label="Curva ilustrativa de frequência cardíaca, não é um eletrocardiograma"><path d="M0 68 12 62 25 69 36 60 48 66 58 49 68 54 79 46 90 57 102 40 113 49 124 30 136 44 147 35 158 49 169 29 181 45 192 35 203 53 214 47 226 59 237 52 248 66 260 55 271 65 283 52 295 63 307 56 320 61"/></svg><div class="detail-time"><span>08:00</span><span>12:00</span><span>16:00</span><span>20:00</span></div><div class="detail-row"><span>Em repouso</span><strong>62 bpm</strong></div><div class="detail-row"><span>Faixa do dia</span><strong>58 — 126 bpm</strong></div><div class="demo-box">Valores e curva fictícios. Esta prévia não mede sinais e não faz avaliações de saúde.</div>`,'heart')}
function sleepSheet(){openSheet('Uma pausa que conta.',`<p class="sheet-kicker">SEU SONO · EXEMPLO</p><div class="detail-value">7<small>h</small> 32<small>min</small></div><p>23:08 — 07:00 · 20 min acordado</p><div class="sleep-phases" aria-label="Fases do sono ilustrativas">${[[13,'#7566a0'],[20,'#c6baf5'],[8,'#cfaee1'],[14,'#7566a0'],[10,'#c6baf5'],[3,'#e2c7b4'],[15,'#cfaee1'],[17,'#c6baf5']].map(([w,c])=>`<span style="flex:${w};background:${c}"></span>`).join('')}</div><div class="detail-time"><span>23:08</span><span>07:00</span></div><div class="sleep-legend"><div><span class="sleep-dot" style="background:#7566a0"></span>Profundo<b>1h 24min</b></div><div><span class="sleep-dot" style="background:#c6baf5"></span>Leve<b>4h 18min</b></div><div><span class="sleep-dot" style="background:#cfaee1"></span>REM<b>1h 50min</b></div><div><span class="sleep-dot" style="background:#e2c7b4"></span>Acordado<b>20min</b></div></div><div class="demo-box">Dados ilustrativos. A disponibilidade das fases do sono dependerá da integração real com a pulseira.</div>`,'sleep')}
let draftFace=state.face;
function facesSheet(reset=true){if(reset)draftFace=state.face;openSheet('Um toque seu.',`<p>Três direções visuais para imaginar o seu mostrador.</p><div class="faces">${[[1,'Ritmo'],[2,'Essencial'],[3,'Noturno']].map(([f,n])=>`<button class="face-option ${draftFace===f?'selected':''}" data-face="${f}" aria-pressed="${draftFace===f}">${watchFace(f)}<span>${n}</span></button>`).join('')}</div><button class="primary-btn" data-action="apply-face">Usar nesta prévia ${icon('check')}</button><div class="demo-box">Conceitos de design. A seleção muda apenas esta ilustração; envio de mostradores para a Fit3 ainda não foi validado.</div>`,'faces')}
let pairStep=0;function pairSheet(step=0){pairStep=step;const titles=['Vamos aproximar.','Tudo no seu lugar.','Um novo começo.'];const desc=['Na experiência final, você aproximará a Fit3 do iPhone e permitirá o uso do Bluetooth.','A próxima etapa mostrará a pulseira encontrada e pedirá a confirmação da conexão.','Esta é a aparência da confirmação. Nesta prévia, nenhum dispositivo foi conectado.'];openSheet('Conectar sua Fit.',`<p class="sheet-kicker">DEMONSTRAÇÃO DO FLUXO</p><div class="connection-steps" aria-label="Etapa ${step+1} de 3">${[0,1,2].map(i=>`<i class="${i<=step?'done':''}"></i>`).join('')}</div><div class="pair-icon">${icon(['bluetooth','watch','check'][step])}</div><h3 class="pair-title">${titles[step]}</h3><p class="pair-copy">${desc[step]}</p><div class="demo-box">${step===1?'Galaxy Fit3 · dispositivo de exemplo':'Simulação visual. Não buscamos pulseiras nem solicitamos permissões reais.'}</div><button class="primary-btn" data-action="pair-next">${step===2?'Concluir demonstração':'Continuar simulação'} ${icon(step===2?'check':'arrow-right')}</button>`,'pair')}
const actions={
close:closeSheet,goal:goalSheet,heart:heartSheet,sleep:sleepSheet,theme,faces:facesSheet,welcome,pair:()=>pairSheet(0),
'start-explore':()=>{closeSheet();navigate('today')},
'save-goal':()=>{state.goal=Number($('#goal-range').value);persist();closeSheet();render();toast('Sua meta foi atualizada nesta prévia.')},
'apply-face':()=>{state.face=draftFace;persist();closeSheet();render();toast('Mostrador atualizado na ilustração.')},
'pair-next':()=>{if(pairStep<2)pairSheet(pairStep+1);else{state.connected=true;closeSheet();render();toast('Demonstração concluída. Nenhuma conexão Bluetooth foi realizada.')}},
notifications:()=>{state.notifications=!state.notifications;render();toast(state.notifications?'Prévia ativada. Nenhuma notificação será enviada.':'Prévia de lembretes desativada.')},
name:()=>{openSheet('Como prefere ser chamado?',`<label class="field-label" for="profile-name">Seu nome</label><input class="name-input" id="profile-name" type="text" autocomplete="given-name" maxlength="28" value="${escapeHTML(state.name)}"><button class="primary-btn" data-action="save-name">Salvar nome</button>`,'name');$('#profile-name').focus()},
'save-name':()=>{const n=$('#profile-name').value.trim();if(!n){$('#profile-name').setCustomValidity('Digite um nome.');$('#profile-name').reportValidity();return;}state.name=n;persist();closeSheet();render();toast('Seu nome foi atualizado.')},
health:()=>openSheet('Tudo em sintonia.',`<p class="sheet-kicker">APPLE SAÚDE · PLANEJADO</p><div class="pair-icon">${icon('heart')}</div><p>A proposta é reunir seus registros no Apple Saúde, com sua permissão e controle sobre cada categoria.</p><div class="info-list"><div class="info-row"><div>Passos e atividade</div><span class="row-value">Planejado</span></div><div class="info-row"><div>Sono e frequência cardíaca</div><span class="row-value">A validar</span></div></div><div class="demo-box">A integração depende da leitura real da Fit3 e da implementação do HealthKit. Esta prévia não lê nem grava dados no Apple Saúde.</div>`),
privacy:()=>openSheet('Seu espaço, respeitado.',`<p>Esta demonstração usa apenas dados fictícios. Não acessa Bluetooth, sensores, localização ou informações de saúde.</p><div class="detail-row"><span>Dados de saúde</span><strong>Nenhum coletado</strong></div><div class="detail-row"><span>Preferências visuais</span><strong>Neste navegador</strong></div><div class="detail-row"><span>Integrações</span><strong>Não ativadas</strong></div><p>Nome, aparência, meta e mostrador são salvos localmente para manter a prévia do seu jeito. Você pode apagá-los abaixo.</p><button class="secondary-btn" data-action="reset-preferences">Restaurar preferências da prévia</button>`),
'reset-preferences':()=>{state.name='Antonio';state.goal=10000;state.theme='dark';state.face=1;state.notifications=false;state.connected=false;persist();applyTheme();closeSheet();render();toast('Preferências da prévia restauradas.')},
sync:()=>openSheet('Seu dia, atualizado.',`<div class="pair-icon">${icon('refresh')}</div><p>A experiência planejada reunirá os dados disponíveis da sua Fit3 e mostrará quando a última sincronização aconteceu.</p><div class="info-list"><div class="info-row"><div>Atividade diária</div><span class="row-value">A validar</span></div><div class="info-row"><div>Sono e coração</div><span class="row-value">A validar</span></div></div><div class="demo-box">Ainda não há leitura ou sincronização real. A disponibilidade de cada dado será confirmada nos testes Bluetooth.</div>`),
'device-info':()=>openSheet('Sobre a sua Fit.',`<div class="detail-row"><span>Dispositivo de referência</span><strong>Samsung Galaxy Fit3</strong></div><div class="detail-row"><span>Modelo</span><strong>SM-R390</strong></div><div class="detail-row"><span>Conexão nesta prévia</span><strong>Simulada</strong></div><div class="detail-row"><span>Bateria de exemplo</span><strong>78%</strong></div><p>O FitΛ é um projeto independente. A interface está em desenvolvimento; a compatibilidade real será verificada em uma próxima etapa.</p>`)
};
document.addEventListener('click',e=>{const target=e.target.closest('button');if(!target)return;if(target.dataset.nav){navigate(target.dataset.nav);return;}if(target.dataset.action){actions[target.dataset.action]?.();return;}if(target.dataset.period){state.period=target.dataset.period;state.weekOffset=0;state.selectedBar=state.period==='week'?6:3;render();return;}if(target.dataset.metric){state.metric=target.dataset.metric;render();return;}if(target.dataset.bar!==undefined){state.selectedBar=Number(target.dataset.bar);render();const b=$(`[data-bar="${state.selectedBar}"]`);b?.focus({preventScroll:true});return;}if(target.dataset.offset){state.weekOffset=Math.max(-1,Math.min(0,state.weekOffset+Number(target.dataset.offset)));render();return;}if(target.dataset.goal){$('#goal-range').value=target.dataset.goal;updateGoalInput();return;}if(target.dataset.face){draftFace=Number(target.dataset.face);facesSheet(false);}});
function updateGoalInput(){$('#goal-value').textContent=fmt(Number($('#goal-range').value));document.querySelectorAll('[data-goal]').forEach(b=>b.classList.toggle('active',b.dataset.goal===$('#goal-range').value))}
document.addEventListener('input',e=>{if(e.target.id==='goal-range')updateGoalInput();if(e.target.id==='profile-name')e.target.setCustomValidity('')});
document.addEventListener('keydown',e=>{if($('#sheet-backdrop').hidden)return;if(e.key==='Escape'){closeSheet();return;}if(e.key==='Enter'&&e.target.id==='profile-name'){actions['save-name']();return;}if(e.key==='Tab'){const focusable=[...$('#sheet').querySelectorAll('button:not([disabled]),input:not([disabled]),[tabindex="0"]')];const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('#sheet'))){e.preventDefault();last?.focus()}else if(!e.shiftKey&&(document.activeElement===last||document.activeElement===$('#sheet'))){e.preventDefault();first?.focus()}}});
$('#sheet-backdrop').addEventListener('click',e=>{if(e.target===$('#sheet-backdrop'))closeSheet()});
$('#studio-theme').addEventListener('click',theme);$('#welcome-button').addEventListener('click',welcome);
mountIcons();applyTheme();render();
